import 'enemy_type.dart';
class EnemyStats { final int hp,damage; final double speed,armor; const EnemyStats({required this.hp,required this.damage,required this.speed,required this.armor}); static EnemyStats forType(EnemyTypeData type,{required int floor,required double difficulty}){final scale=1+floor*.075;return EnemyStats(hp:(type.hp*scale*difficulty).round(),damage:(4*scale*difficulty).round().clamp(1,999),speed:type.speed,armor:type.armor);} }
